using System;
using System.Net;
using System.Collections.Generic;
using System.Data.Odbc;
using System.Text;
using System.Security.Cryptography;
using System.Web.Script.Serialization;

internal sealed partial class HPAddressClient
{
 static string Quoted(string s){return "\""+s.Replace("\"","\"\"")+"\"";}
 static string FullHash(string s){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(s))).Replace("-","").ToLowerInvariant();}
 Dictionary<int,string> FullRead(Dictionary<string,object> p,List<Dictionary<string,object>> page){
  var fields=new List<string>();var rawFields=(System.Collections.ArrayList)p["fields"];foreach(Dictionary<string,object> f in rawFields)fields.Add(Convert.ToString(f["name"]));
  var grouped=new Dictionary<int,List<Dictionary<string,object>>>();foreach(var a in page)grouped[Convert.ToInt32(a["nummer"])]=new List<Dictionary<string,object>>();
  string adr=Convert.ToString(p["adr"]);var placeholders=new List<string>();foreach(var a in page)placeholders.Add("?");
  var cols=new List<string>();foreach(string f in fields)cols.Add(Quoted(f));
  var order=new List<string>();foreach(object f in (System.Collections.ArrayList)p["pk"])order.Add(Quoted(Convert.ToString(f)));
  string sql="SELECT "+String.Join(",",cols)+" FROM "+Quoted(Convert.ToString(p["table"]))+" WHERE "+Quoted(adr)+" IN ("+String.Join(",",placeholders)+")";
  var filter=p.ContainsKey("filter")?p["filter"] as Dictionary<string,object>:null;if(filter!=null)foreach(var f in filter)sql+=" AND "+Quoted(f.Key)+"=?";sql+=" ORDER BY "+String.Join(",",order);
  using(var c=Open())using(var cmd=new OdbcCommand(sql,c)){cmd.CommandTimeout=60;foreach(var a in page)cmd.Parameters.Add("adr",OdbcType.Int).Value=Convert.ToInt32(a["nummer"]);if(filter!=null)foreach(var f in filter)cmd.Parameters.Add("filter",OdbcType.VarChar,30).Value=Convert.ToString(f.Value);
   using(var r=cmd.ExecuteReader()){int size=0;while(r.Read()){int n=Convert.ToInt32(r[adr]);if(!grouped.ContainsKey(n)||grouped[n].Count>=5000)throw new InvalidOperationException("Adressbereich zu groß.");var row=new Dictionary<string,object>();foreach(string f in fields){object v=r[f];string text=v==DBNull.Value?null:v is bool?((bool)v?"1":"0"):Convert.ToString(v,System.Globalization.CultureInfo.InvariantCulture).TrimEnd(' ');size+=text==null?0:text.Length;if(size>16000000)throw new InvalidOperationException("Adressbereich zu groß.");row.Add(f,text);}grouped[n].Add(row);}}
  }
  var payload=new Dictionary<int,string>();foreach(var pair in grouped){string value=json.Serialize(pair.Value);if(Encoding.UTF8.GetByteCount(value)>1500000)throw new InvalidOperationException("Adressbereich zu groß.");payload[pair.Key]=value;}return payload;
 }
 void FullPage(List<Dictionary<string,object>> page,Action<string> log){
  var definitions=json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(Convert.FromBase64String(FullSpecBase64)));
  foreach(var def in definitions){
   Dictionary<int,string> snapshots;
   try{snapshots=FullRead((Dictionary<string,object>)def.Value,page);}catch(OdbcException e){string state=e.Errors.Count>0?e.Errors[0].SQLState:"ODBC";log("HP-Bereich "+def.Key+": Leseprüfung "+state+". Andere Bereiche laufen weiter.");foreach(var a in page)Post("bereiche/fehler",new{datenbank=database,nummer=Convert.ToInt32(a["nummer"]),bereich=def.Key,code="ODBC_"+state});continue;}catch(InvalidOperationException){log("HP-Bereich "+def.Key+": Größen- oder Zuordnungsprüfung angehalten. Keine unvollständige Übernahme.");continue;}
   var prints=new List<object>();foreach(var s in snapshots)prints.Add(new{nummer=s.Key,bereich=def.Key,hash=FullHash(s.Value)});
   var reply=Post("bereiche/vergleich",new{datenbank=database,fingerprints=prints});var needed=reply["benoetigt"] as System.Collections.ArrayList;if(needed==null)throw new InvalidOperationException();
   int count=0,size=0;var batch=new List<object>();
   foreach(Dictionary<string,object> n in needed){int number=Convert.ToInt32(n["nummer"]);if(Convert.ToString(n["bereich"])!=def.Key||!snapshots.ContainsKey(number))throw new InvalidOperationException();
    var item=new{nummer=number,bereich=def.Key,daten_json=snapshots[number]};int bytes=Encoding.UTF8.GetByteCount(json.Serialize(item));
    if(bytes>1700000){log("HP-Adressbereich zu groß für eine vollständige Übertragung; keine Teilübernahme.");continue;}
    if(batch.Count>0&&size+bytes>1700000){count+=FullSend(batch,log);batch.Clear();size=0;}batch.Add(item);size+=bytes;
   }
   if(batch.Count>0)count+=FullSend(batch,log);
   log("HP-Bereich "+def.Key+": "+snapshots.Count+" Adressen gelesen, "+count+" neue/geänderte Bereiche übernommen.");
  }
 }
 int FullSend(List<object> entries,Action<string> log){var reply=Post("bereiche/stapel",new{datenbank=database,eintraege=entries});var results=reply["ergebnisse"] as System.Collections.ArrayList;if(results==null||results.Count!=entries.Count)throw new InvalidOperationException();int count=0;foreach(Dictionary<string,object> r in results){if(r.ContainsKey("ok")&&Convert.ToBoolean(r["ok"]))count++;else log("HP-Adressbereich zur Prüfung angehalten. Andere Adressen laufen weiter.");}return count;}
 const string FullSpecBase64="";
}
